多租户 SaaS 架构实战
2026 年 SaaS 全景：隔离模式（共享&#x2F;池化&#x2F;独立） · 数据分片 · 租户上下文 · 计费引擎 · 配额管理 · 灰度发布。

1. 多租户隔离模式1.1 三种隔离模式对比┌─────────────────────────────────────────────────────────────┐│  Silo（独立部署）      Pool（共享实例）      Bridge（混合）    ││  ┌─────┐ ┌─────┐      ┌─────────────┐     ┌─────────────┐  ││  │ T1  │ │ T2  │      │  T1 │ T2 │ T3│     │  T1 (独立)   │  ││  │ DB  │ │ DB  │      │     DB      │     │  T2+T3 (共享) │  ││  └─────┘ └─────┘      └─────────────┘     └─────────────┘  ││  最高隔离，成本最高    成本最优，隔离较弱   按客户等级混合      │└─────────────────────────────────────────────────────────────┘




模式
隔离级别
成本
运维复杂度
适用场景



Silo
最高
高
高
企业版、合规要求


Pool
低
低
低
标准版、中小企业


Bridge
中
中
中
混合策略


1.2 数据隔离策略共享数据库，共享 Schema（最简单）  → tenant_id 字段区分  → 适合：小租户、成本敏感共享数据库，独立 Schema（推荐）  → 每个租户独立 Schema  → 适合：中等规模、需要逻辑隔离独立数据库（最安全）  → 每个租户独立数据库实例  → 适合：大企业、合规要求

2. 租户上下文传播2.1 Spring Boot 多租户架构// 租户上下文public class TenantContext &#123;    private static final ThreadLocal&lt;String&gt; CURRENT_TENANT = new InheritableThreadLocal&lt;&gt;();    public static void setTenantId(String tenantId) &#123;        CURRENT_TENANT.set(tenantId);    &#125;    public static String getTenantId() &#123;        return CURRENT_TENANT.get();    &#125;    public static void clear() &#123;        CURRENT_TENANT.remove();    &#125;&#125;// 租户解析拦截器@Componentpublic class TenantInterceptor implements HandlerInterceptor &#123;    @Override    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) &#123;        String tenantId = extractTenantId(request);        if (tenantId == null) &#123;            throw new TenantNotFoundException(&quot;Tenant not found in request&quot;);        &#125;        TenantContext.setTenantId(tenantId);        return true;    &#125;    @Override    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) &#123;        TenantContext.clear();    &#125;    private String extractTenantId(HttpServletRequest request) &#123;        // 优先级：Header &gt; Subdomain &gt; JWT Claim        String headerTenant = request.getHeader(&quot;X-Tenant-ID&quot;);        if (headerTenant != null) return headerTenant;        String subdomain = extractSubdomain(request);        if (subdomain != null) return resolveTenantFromSubdomain(subdomain);        String token = request.getHeader(&quot;Authorization&quot;);        if (token != null &amp;&amp; token.startsWith(&quot;Bearer &quot;)) &#123;            return extractTenantFromJwt(token.substring(7));        &#125;        return null;    &#125;&#125;

2.2 多租户数据源路由// 动态数据源路由public class TenantRoutingDataSource extends AbstractRoutingDataSource &#123;    private final Map&lt;String, DataSource&gt; tenantDataSources = new ConcurrentHashMap&lt;&gt;();    @Override    protected Object determineCurrentLookupKey() &#123;        return TenantContext.getTenantId();    &#125;    public void registerTenant(String tenantId, DataSource dataSource) &#123;        tenantDataSources.put(tenantId, dataSource);        super.afterPropertiesSet();    &#125;    @Override    protected DataSource determineTargetDataSource() &#123;        String tenantId = TenantContext.getTenantId();        DataSource dataSource = tenantDataSources.get(tenantId);        if (dataSource == null) &#123;            throw new TenantDataSourceNotFoundException(&quot;No datasource for tenant: &quot; + tenantId);        &#125;        return dataSource;    &#125;&#125;// 配置类@Configurationpublic class MultiTenantConfig &#123;    @Bean    public DataSource dataSource(TenantRepository tenantRepository) &#123;        TenantRoutingDataSource routingDataSource = new TenantRoutingDataSource();                // 加载所有租户数据源        Map&lt;Object, Object&gt; targetDataSources = new HashMap&lt;&gt;();        tenantRepository.findAll().forEach(tenant -&gt; &#123;            DataSource ds = createDataSource(tenant);            targetDataSources.put(tenant.getId(), ds);        &#125;);                routingDataSource.setTargetDataSources(targetDataSources);        return routingDataSource;    &#125;&#125;

2.3 Hibernate 多租户// Schema 级隔离public class SchemaMultiTenantConnectionProvider implements MultiTenantConnectionProvider &#123;    private final DataSource dataSource;    @Override    public Connection getAnyConnection() throws SQLException &#123;        return dataSource.getConnection();    &#125;    @Override    public Connection getConnection(String tenantIdentifier) throws SQLException &#123;        Connection connection = dataSource.getConnection();        connection.createStatement().execute(&quot;SET schema &#x27;&quot; + tenantIdentifier + &quot;&#x27;&quot;);        return connection;    &#125;&#125;public class TenantSchemaResolver implements CurrentTenantIdentifierResolver &#123;    @Override    public String resolveCurrentTenantIdentifier() &#123;        return TenantContext.getTenantId();    &#125;&#125;// JPA 配置@Configurationpublic class HibernateConfig &#123;    @Bean    public LocalContainerEntityManagerFactoryBean entityManagerFactory(            DataSource dataSource, MultiTenantConnectionProvider connectionProvider,            CurrentTenantIdentifierResolver tenantResolver) &#123;                LocalContainerEntityManagerFactoryBean em = new LocalContainerEntityManagerFactoryBean();        em.setDataSource(dataSource);        em.setPackagesToScan(&quot;com.example.model&quot;);        em.setJpaVendorAdapter(new HibernateJpaVendorAdapter());                Map&lt;String, Object&gt; jpaProperties = new HashMap&lt;&gt;();        jpaProperties.put(Environment.MULTI_TENANT, MultiTenancyStrategy.SCHEMA);        jpaProperties.put(Environment.MULTI_TENANT_CONNECTION_PROVIDER, connectionProvider);        jpaProperties.put(Environment.MULTI_TENANT_IDENTIFIER_RESOLVER, tenantResolver);        em.setJpaPropertyMap(jpaProperties);                return em;    &#125;&#125;

3. 数据分片（共享数据库）3.1 行级隔离（tenant_id）// 实体基类@MappedSuperclasspublic abstract class TenantAwareEntity &#123;    @Column(name = &quot;tenant_id&quot;, nullable = false)    private String tenantId;    @PrePersist    protected void onCreate() &#123;        this.tenantId = TenantContext.getTenantId();    &#125;&#125;// 自动过滤@FilterDef(name = &quot;tenantFilter&quot;, parameters = @ParamDef(name = &quot;tenantId&quot;, type = String.class))@Filter(name = &quot;tenantFilter&quot;, condition = &quot;tenant_id = :tenantId&quot;)@Entitypublic class Order extends TenantAwareEntity &#123;    @Id    private String id;    private String customerId;    private BigDecimal amount;&#125;// 自动应用过滤器@Componentpublic class TenantFilterApplier &#123;    @PersistenceContext    private EntityManager entityManager;    @PostConstruct    public void enableTenantFilter() &#123;        Session session = entityManager.unwrap(Session.class);        session.enableFilter(&quot;tenantFilter&quot;)               .setParameter(&quot;tenantId&quot;, TenantContext.getTenantId());    &#125;&#125;

3.2 分区表优化-- PostgreSQL 分区表CREATE TABLE orders (    id UUID,    tenant_id VARCHAR(64) NOT NULL,    customer_id VARCHAR(64) NOT NULL,    amount DECIMAL(10,2),    created_at TIMESTAMP,    PRIMARY KEY (tenant_id, id)) PARTITION BY LIST (tenant_id);-- 为大租户创建独立分区CREATE TABLE orders_tenant_001 PARTITION OF orders FOR VALUES IN (&#x27;tenant-001&#x27;);CREATE TABLE orders_tenant_002 PARTITION OF orders FOR VALUES IN (&#x27;tenant-002&#x27;);-- 默认分区（小租户）CREATE TABLE orders_default PARTITION OF orders DEFAULT;-- 自动创建分区（按需）CREATE OR REPLACE FUNCTION create_tenant_partition(p_tenant_id VARCHAR) RETURNS VOID AS $$BEGIN    EXECUTE format(&#x27;CREATE TABLE IF NOT EXISTS orders_%I PARTITION OF orders FOR VALUES IN (%L)&#x27;,                   p_tenant_id, p_tenant_id);END;$$ LANGUAGE plpgsql;

4. 租户管理4.1 租户生命周期@Servicepublic class TenantService &#123;    private final TenantRepository tenantRepository;    private final DataSourceManager dataSourceManager;    private final ProvisioningService provisioningService;    @Transactional    public Tenant createTenant(CreateTenantRequest request) &#123;        // 1. 创建租户记录        Tenant tenant = Tenant.builder()            .id(UUID.randomUUID().toString())            .name(request.getName())            .plan(request.getPlan())            .status(TenantStatus.PROVISIONING)            .createdAt(Instant.now())            .build();        tenantRepository.save(tenant);        try &#123;            // 2. 初始化资源            switch (tenant.getPlan()) &#123;                case ENTERPRISE -&gt; provisionSiloTenant(tenant);                case BUSINESS -&gt; provisionSchemaTenant(tenant);                case STARTER -&gt; provisionSharedTenant(tenant);            &#125;            // 3. 创建管理员账号            provisioningService.createAdminUser(tenant);            // 4. 初始化默认配置            provisioningService.initializeDefaults(tenant);            tenant.setStatus(TenantStatus.ACTIVE);        &#125; catch (Exception e) &#123;            tenant.setStatus(TenantStatus.FAILED);            throw new ProvisioningException(&quot;Failed to provision tenant&quot;, e);        &#125;        return tenantRepository.save(tenant);    &#125;    @Transactional    public void suspendTenant(String tenantId) &#123;        Tenant tenant = tenantRepository.findById(tenantId)            .orElseThrow(() -&gt; new TenantNotFoundException(tenantId));                tenant.setStatus(TenantStatus.SUSPENDED);        tenantRepository.save(tenant);        // 禁用数据源连接        dataSourceManager.disableTenant(tenantId);    &#125;    @Transactional    public void deleteTenant(String tenantId) &#123;        Tenant tenant = tenantRepository.findById(tenantId)            .orElseThrow(() -&gt; new TenantNotFoundException(tenantId));                tenant.setStatus(TenantStatus.DELETED);        tenantRepository.save(tenant);        // 异步清理资源        provisioningService.cleanupTenantResources(tenantId);    &#125;&#125;

4.2 租户配额管理// 配额定义public class TenantQuotas &#123;    private int maxUsers;    private long storageBytes;    private int apiCallsPerMonth;    private int maxProjects;    private List&lt;String&gt; enabledFeatures;    public static TenantQuotas forPlan(TenantPlan plan) &#123;        return switch (plan) &#123;            case STARTER -&gt; new TenantQuotas(5, 1_000_000_000L, 10_000, 3, List.of(&quot;basic&quot;));            case BUSINESS -&gt; new TenantQuotas(50, 50_000_000_000L, 100_000, 50, List.of(&quot;basic&quot;, &quot;advanced&quot;));            case ENTERPRISE -&gt; new TenantQuotas(-1, -1L, -1, -1, List.of(&quot;all&quot;));        &#125;;    &#125;&#125;// 配额检查@Componentpublic class QuotaService &#123;    private final TenantRepository tenantRepository;    private final UsageRepository usageRepository;    public void checkQuota(String tenantId, ResourceType resource) &#123;        Tenant tenant = tenantRepository.findById(tenantId).orElseThrow();        TenantQuotas quotas = TenantQuotas.forPlan(tenant.getPlan());        Usage usage = usageRepository.findByTenantId(tenantId);        switch (resource) &#123;            case USER -&gt; &#123;                if (quotas.getMaxUsers() &gt; 0 &amp;&amp; usage.getUserCount() &gt;= quotas.getMaxUsers()) &#123;                    throw new QuotaExceededException(&quot;User limit reached&quot;);                &#125;            &#125;            case STORAGE -&gt; &#123;                if (quotas.getStorageBytes() &gt; 0 &amp;&amp; usage.getStorageBytes() &gt;= quotas.getStorageBytes()) &#123;                    throw new QuotaExceededException(&quot;Storage limit reached&quot;);                &#125;            &#125;            case API_CALL -&gt; &#123;                if (quotas.getApiCallsPerMonth() &gt; 0 &amp;&amp; usage.getApiCallsThisMonth() &gt;= quotas.getApiCallsPerMonth()) &#123;                    throw new QuotaExceededException(&quot;API call limit reached&quot;);                &#125;            &#125;        &#125;    &#125;&#125;

5. 计费系统5.1 订阅计费模型// 订阅计划@Entitypublic class SubscriptionPlan &#123;    @Id    private String id;    private String name;    private BigDecimal monthlyPrice;    private BigDecimal yearlyPrice;    @ElementCollection    private List&lt;String&gt; features;    private TenantQuotas quotas;&#125;// 订阅@Entitypublic class Subscription &#123;    @Id    private String id;    private String tenantId;    private String planId;    private BillingCycle billingCycle;    private Instant currentPeriodStart;    private Instant currentPeriodEnd;    private SubscriptionStatus status;&#125;// 计费服务@Servicepublic class BillingService &#123;    private final SubscriptionRepository subscriptionRepository;    private final PaymentGateway paymentGateway;    private final InvoiceService invoiceService;    @Scheduled(cron = &quot;0 0 0 1 * *&quot;) // 每月 1 号    public void processMonthlyBilling() &#123;        List&lt;Subscription&gt; activeSubscriptions = subscriptionRepository.findActiveByBillingCycle(BillingCycle.MONTHLY);                for (Subscription subscription : activeSubscriptions) &#123;            try &#123;                // 生成账单                Invoice invoice = invoiceService.generateInvoice(subscription);                                // 扣款                PaymentResult result = paymentGateway.charge(subscription.getTenantId(), invoice.getAmount());                                if (result.isSuccess()) &#123;                    subscription.setCurrentPeriodStart(Instant.now());                    subscription.setCurrentPeriodEnd(Instant.now().plusMonths(1));                    subscriptionRepository.save(subscription);                &#125; else &#123;                    handlePaymentFailure(subscription, result);                &#125;            &#125; catch (Exception e) &#123;                log.error(&quot;Billing failed for tenant: &#123;&#125;&quot;, subscription.getTenantId(), e);            &#125;        &#125;    &#125;&#125;

5.2 用量计费（Metered Billing）// 用量记录@Entitypublic class UsageRecord &#123;    @Id    private String id;    private String tenantId;    private String metricName;    private BigDecimal quantity;    private Instant timestamp;&#125;// 用量聚合@Servicepublic class UsageAggregationService &#123;    private final UsageRecordRepository usageRepository;    private final MeteredBillingRepository meteredBillingRepository;    @Scheduled(cron = &quot;0 0 0 * * *&quot;) // 每天    public void aggregateDailyUsage() &#123;        Instant start = Instant.now().minus(Duration.ofDays(1));        Instant end = Instant.now();        List&lt;TenantUsage&gt; usageList = usageRepository.aggregateByTenant(start, end);        for (TenantUsage usage : usageList) &#123;            MeteredBilling billing = meteredBillingRepository                .findByTenantIdAndPeriod(usage.getTenantId(), start, end)                .orElseGet(() -&gt; createNewBilling(usage.getTenantId(), start, end));            billing.addUsage(usage.getMetricName(), usage.getQuantity());            meteredBillingRepository.save(billing);        &#125;    &#125;&#125;// Stripe 集成@Servicepublic class StripeBillingService &#123;    private final StripeClient stripeClient;    public void reportUsage(String tenantId, String subscriptionItemId, long quantity) &#123;        stripeClient.subscriptionItems().createUsageRecord(subscriptionItemId,             UsageRecordCreateParams.builder()                .setQuantity(quantity)                .setTimestamp(Instant.now().getEpochSecond())                .build());    &#125;&#125;

6. 灰度发布与特性开关6.1 租户级特性开关// 特性开关服务@Servicepublic class FeatureFlagService &#123;    private final FeatureFlagRepository featureFlagRepository;    private final Cache&lt;String, Set&lt;String&gt;&gt; tenantFeaturesCache;    public boolean isEnabled(String featureKey, String tenantId) &#123;        Set&lt;String&gt; enabledFeatures = tenantFeaturesCache.get(tenantId,             () -&gt; featureFlagRepository.findEnabledFeatures(tenantId));        return enabledFeatures.contains(featureKey);    &#125;    public void enableFeature(String featureKey, String tenantId) &#123;        featureFlagRepository.enable(featureKey, tenantId);        tenantFeaturesCache.invalidate(tenantId);    &#125;&#125;// 特性开关注解@Target(&#123;ElementType.METHOD, ElementType.TYPE&#125;)@Retention(RetentionPolicy.RUNTIME)public @interface RequiresFeature &#123;    String value();&#125;@Aspect@Componentpublic class FeatureFlagAspect &#123;    @Autowired    private FeatureFlagService featureFlagService;    @Before(&quot;@annotation(requiresFeature)&quot;)    public void checkFeature(RequiresFeature requiresFeature) &#123;        String tenantId = TenantContext.getTenantId();        if (!featureFlagService.isEnabled(requiresFeature.value(), tenantId)) &#123;            throw new FeatureNotEnabledException(requiresFeature.value());        &#125;    &#125;&#125;// 使用@RestControllerpublic class AdvancedReportController &#123;    @RequiresFeature(&quot;advanced-reports&quot;)    @GetMapping(&quot;/api/reports/advanced&quot;)    public AdvancedReport getAdvancedReport() &#123;        // ...    &#125;&#125;

6.2 租户级灰度发布// 灰度路由@Componentpublic class TenantAwareRouter &#123;    private final TenantRepository tenantRepository;    private final LoadBalancer loadBalancer;    public ServiceInstance route(String tenantId, String serviceId) &#123;        Tenant tenant = tenantRepository.findById(tenantId).orElseThrow();                // 根据租户版本路由        String version = tenant.getAppVersion();        List&lt;ServiceInstance&gt; instances = loadBalancer.getInstances(serviceId, version);                if (instances.isEmpty()) &#123;            // 回退到稳定版本            instances = loadBalancer.getInstances(serviceId, &quot;stable&quot;);        &#125;                return instances.get(ThreadLocalRandom.current().nextInt(instances.size()));    &#125;&#125;

7. 安全与合规7.1 租户数据隔离审计// 审计日志@Entitypublic class AuditLog &#123;    @Id    private String id;    private String tenantId;    private String userId;    private String action;    private String resource;    private String resourceId;    private Map&lt;String, Object&gt; details;    private Instant timestamp;    private String ipAddress;&#125;// 自动审计@Aspect@Componentpublic class AuditAspect &#123;    @Autowired    private AuditLogRepository auditLogRepository;    @AfterReturning(pointcut = &quot;@annotation(Audited)&quot;, returning = &quot;result&quot;)    public void audit(JoinPoint joinPoint, Object result) &#123;        Audited audited = getAnnotation(joinPoint);                AuditLog log = new AuditLog();        log.setTenantId(TenantContext.getTenantId());        log.setUserId(getCurrentUserId());        log.setAction(audited.action());        log.setResource(audited.resource());        log.setTimestamp(Instant.now());                auditLogRepository.save(log);    &#125;&#125;

7.2 数据加密// 租户级加密密钥@Entitypublic class TenantEncryptionKey &#123;    @Id    private String tenantId;    private String encryptedKey;    private String keyVersion;    private Instant rotatedAt;&#125;// 加密拦截器@Componentpublic class EncryptionInterceptor implements EmptyInterceptor &#123;    @Autowired    private TenantKeyService keyService;    @Override    public boolean onSave(Object entity, Serializable id, Object[] state, String[] propertyNames, Type[] types) &#123;        if (entity instanceof Encryptable) &#123;            encryptFields(entity, state, propertyNames);        &#125;        return false;    &#125;    @Override    public boolean onLoad(Object entity, Serializable id, Object[] state, String[] propertyNames, Type[] types) &#123;        if (entity instanceof Encryptable) &#123;            decryptFields(entity, state, propertyNames);        &#125;        return false;    &#125;    private void encryptFields(Object entity, Object[] state, String[] propertyNames) &#123;        String tenantId = TenantContext.getTenantId();        SecretKey key = keyService.getKey(tenantId);        for (int i = 0; i &lt; propertyNames.length; i++) &#123;            if (state[i] instanceof String &amp;&amp; isEncryptedField(entity, propertyNames[i])) &#123;                state[i] = encrypt((String) state[i], key);            &#125;        &#125;    &#125;&#125;

8. 监控与告警8.1 租户级指标// 租户指标@Componentpublic class TenantMetrics &#123;    private final MeterRegistry registry;    public void recordApiCall(String tenantId, String endpoint, int statusCode, long duration) &#123;        Timer.builder(&quot;tenant.api.duration&quot;)            .tag(&quot;tenant&quot;, tenantId)            .tag(&quot;endpoint&quot;, endpoint)            .tag(&quot;status&quot;, String.valueOf(statusCode))            .register(registry)            .record(Duration.ofMillis(duration));        Counter.builder(&quot;tenant.api.calls&quot;)            .tag(&quot;tenant&quot;, tenantId)            .tag(&quot;endpoint&quot;, endpoint)            .register(registry)            .increment();    &#125;    public void recordResourceUsage(String tenantId, String resource, long usage) &#123;        Gauge.builder(&quot;tenant.resource.usage&quot;, () -&gt; usage)            .tag(&quot;tenant&quot;, tenantId)            .tag(&quot;resource&quot;, resource)            .register(registry);    &#125;&#125;// 租户健康检查@Componentpublic class TenantHealthIndicator implements HealthIndicator &#123;    @Autowired    private TenantRepository tenantRepository;    @Override    public Health health() &#123;        long activeTenants = tenantRepository.countByStatus(TenantStatus.ACTIVE);        long failedTenants = tenantRepository.countByStatus(TenantStatus.FAILED);        if (failedTenants &gt; 0) &#123;            return Health.down()                .withDetail(&quot;active&quot;, activeTenants)                .withDetail(&quot;failed&quot;, failedTenants)                .build();        &#125;        return Health.up()            .withDetail(&quot;active&quot;, activeTenants)            .build();    &#125;&#125;

9. 典型案例：多租户隔离方案落地问题背景：一家 B2B CRM SaaS 从 30 家客户增长到 3000 家。最初所有租户共库共表（tenant_id 行级隔离），某大客户（金融行业）要求「数据物理隔离 + 审计合规」，而长尾客户对价格敏感、必须摊薄成本——单一隔离模式两头不讨好。
方案：采用 Bridge（混合）模式：按客户等级路由到不同隔离单元，租户上下文全链路传播：
                     ┌──────────────────────────────┐ 请求(带 JWT/租户ID)  │  网关：解析租户 → 路由决策       │───────────────────→ │   · VIP/合规租户 → Silo Cell   │                     │   · 标准租户   → Pool 共享池    │                     └──────┬───────────────┬───────┘                            ▼               ▼                  ┌──────────────┐  ┌──────────────────────┐                  │ Cell-A(独享)  │  │ Pool 共享集群          │                  │ 独立 K8s 命名  │  │ 应用 + PG Schema 隔离  │                  │ 空间 + 独立 DB │  │ tenant_id 行级隔离     │                  └──────────────┘  └──────────────────────┘




客户等级
隔离模式
数据策略
成本归属



金融&#x2F;旗舰客户
Silo（独立部署）
独立数据库实例
独享计费


中型客户
Pool
共享库、独立 Schema
按量分摊


长尾&#x2F;免费客户
Pool
共享 Schema + tenant_id
成本最优


关键设计：
// 1. 租户上下文：入口解析一次，全链路透传（MDC + ThreadLocal）public class TenantContext &#123;    private static final ThreadLocal&lt;String&gt; CURRENT = new ThreadLocal&lt;&gt;();    public static void set(String tenantId) &#123; CURRENT.set(tenantId); MDC.put(&quot;tenantId&quot;, tenantId); &#125;    // 日志带 tenantId：排查问题不再跨租户大海捞针    public static void clear() &#123; CURRENT.remove(); MDC.remove(&quot;tenantId&quot;); &#125;  // 线程池复用必须清理！&#125;// 2. Hibernate 多租户：Schema 策略自动路由public class SchemaTenantResolver implements CurrentTenantIdentifierResolver, HibernatePropertiesCustomizer &#123;    @Override    public String resolveCurrentTenantIdentifier() &#123;        return TenantContext.get();                       // 连接池按租户切 Schema    &#125;    // 关键配置：hibernate.multiTenancy=SCHEMA + 租户连接提供器&#125;// 3. 行级隔离的最后一道防线：PostgreSQL RLS（数据库层强制，应用漏了也漏不出数据）// CREATE POLICY tenant_isolation ON deals//   USING (tenant_id = current_setting(&#x27;app.tenant_id&#x27;)::uuid);// 连接池每次借出连接执行：SET app.tenant_id = &#x27;&lt;当前租户&gt;&#x27;

踩坑点：① 定时任务和 MQ 消费线程没有租户上下文，TenantContext.get() 返回 null，把 A 租户的数据写给 B——所有异步入口必须显式携带并恢复租户 ID（消息头&#x2F;任务参数）。② 线程池复用线程未 clear()，上一个请求的租户 ID “粘”到下一个请求，属于最隐蔽的越权。③ 缓存 key 不带租户（deals:list），A 公司看到 B 公司的客户列表——缓存键一律 t:{tenantId}:deals:list。④ 只靠应用层 WHERE tenant_id，一次手写 SQL 的报表功能漏了条件就跨租户——上 RLS 后这类事故归零。
10. 常见误用与陷阱


坑
现象&#x2F;后果
解法



租户上下文不清理
线程复用后串租户（隐蔽越权）
请求结束 finally clear() + 接口强制非空


异步链路丢租户
MQ&#x2F;定时任务查不到数据或查错数据
消息头&#x2F;任务参数携带租户 ID，消费端恢复


缓存 key 不带租户
跨租户读到对方数据
键名统一 t:{tenantId}:... 前缀


只靠应用层过滤
手写 SQL 漏 WHERE 就跨租户
PostgreSQL RLS &#x2F; 行级策略兜底


大租户拖垮共享池
一个大客户的导出任务打爆 Pool
大租户迁 Silo；共享池配额&#x2F;并发限制


Schema 迁移漂移
3000 个 Schema 结构不一致
Flyway 按租户循环执行 + 版本对账


配额只在应用层
客户端并发把系统打挂
网关租户级限流 + 存储&#x2F;算力硬配额


日志无租户标识
跨租户问题排查无从下手
MDC 注入 tenantId，日志平台按租户检索


计费与用量脱节
大用量客户按低档付费
用量事件化上报 + 账期对账


11. 速查卡片隔离选型  = Silo(合规/大客户) Pool(长尾) Bridge(混合路由)数据策略  = 共享Schema+tenant_id / 独立Schema / 独立DB上下文    = 网关解析 → ThreadLocal/MDC → 异步链路显式透传兜底防线  = DB 层 RLS 行级策略；缓存 key 带租户前缀配额      = 网关限流 + 存储/并发硬配额（应用层只是软限制）运维      = Flyway 全租户迁移 + 版本对账；日志按租户可检索

12. 总结12.1 架构决策清单
 选择隔离模式（Silo&#x2F;Pool&#x2F;Bridge）
 确定数据隔离策略（共享&#x2F;Schema&#x2F;独立）
 设计租户上下文传播机制
 实现配额管理与计费系统
 配置租户级特性开关
 建立审计与合规机制
 部署租户级监控

12.2 2026 趋势
Pool 模式主流：成本优化驱动共享架构
Schema 隔离普及：平衡安全与成本
Usage-based 计费：按量付费成为标准
租户级可观测性：精细化运营

