成本模型 按实例&#x2F;时间 按请求数&#x2F;CPU 时间
2. Cloudflare Workers 深度实战2.1 Workers 运行时架构┌─────────────────────────────────────────┐│ Cloudflare 全球网络 ││ 300+ 数据中心 · 覆盖 95% 互联网用户 │├─────────────────────────────────────────┤│ V8 Isolate（每个 Worker 独立沙箱） ││ ├── 冷启动 &lt; 5ms ││ ├── 内存限制 128MB ││ └── CPU 时间 30s（付费） │├─────────────────────────────────────────┤│ 绑定资源（Bindings） ││ ├── KV / R2 / D1 / Durable Objects ││ ├── Queues / Vectorize / AI ││ └── Hyperdrive / Browser Rendering │└─────────────────────────────────────────┘
2.2 Worker 基础开发// src/index.ts - Cloudflare Worker 入口export interface Env &#123; KV: KVNamespace; DB: D1Database; QUEUE: Queue&lt;AnalyticsEvent&gt;; COUNTER: DurableObjectNamespace;&#125;export default &#123; async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise&lt;Response&gt; &#123; const url = new URL(request.url); // 边缘路由 if (url.pathname.startsWith(&#x27;/api/&#x27;)) &#123; return handleAPI(request, env); &#125; if (url.pathname.startsWith(&#x27;/realtime/&#x27;)) &#123; return handleWebSocket(request, env); &#125; // 边缘缓存 + SSR const cacheKey = new Request(url.toString(), request); const cache = caches.default; let response = await cache.match(cacheKey); if (!response) &#123; response = await renderPage(url, env); // 边缘缓存 60 秒 response = new Response(response.body, &#123; ...response, headers: &#123; ...Object.fromEntries(response.headers), &#x27;Cache-Control&#x27;: &#x27;s-maxage=60, stale-while-revalidate=300&#x27;, &#125;, &#125;); ctx.waitUntil(cache.put(cacheKey, response.clone())); &#125; return response; &#125;,&#125;;async function handleAPI(request: Request, env: Env): Promise&lt;Response&gt; &#123; const url = new URL(request.url); // D1 数据库查询（边缘 SQLite） const users = await env.DB .prepare(&#x27;SELECT id, name, email FROM users WHERE active = ? LIMIT ?&#x27;) .bind(1, 50) .all(); // KV 缓存热点数据 const cacheKey = `api:users:$&#123;url.searchParams.get(&#x27;page&#x27;) || &#x27;1&#x27;&#125;`; const cached = await env.KV.get(cacheKey, &#x27;json&#x27;); if (cached) &#123; return Response.json(cached, &#123; headers: &#123; &#x27;X-Cache&#x27;: &#x27;HIT&#x27; &#125;, &#125;); &#125; const result = &#123; users: users.results, total: users.meta.total &#125;; await env.KV.put(cacheKey, JSON.stringify(result), &#123; expirationTtl: 300 &#125;); return Response.json(result, &#123; headers: &#123; &#x27;X-Cache&#x27;: &#x27;MISS&#x27; &#125;, &#125;);&#125;
2.3 Durable Objects 有状态边缘计算// src/counter.ts - 分布式计数器export class RequestCounter &#123; private count: number = 0; private state: DurableObjectState; constructor(state: DurableObjectState, env: Env) &#123; this.state = state; state.blockConcurrencyWhile(async () =&gt; &#123; const stored = await state.storage.get&lt;number&gt;(&#x27;count&#x27;); this.count = stored ?? 0; &#125;); &#125; async fetch(request: Request) &#123; const url = new URL(request.url); if (url.pathname === &#x27;/increment&#x27;) &#123; this.count++; await this.state.storage.put(&#x27;count&#x27;, this.count); return Response.json(&#123; count: this.count &#125;); &#125; if (url.pathname === &#x27;/get&#x27;) &#123; return Response.json(&#123; count: this.count &#125;); &#125; // WebSocket 实时推送 if (url.pathname === &#x27;/ws&#x27;) &#123; const [client, server] = Object.values(new TransformStream&lt;WebSocket&gt;()) as any; this.state.acceptWebSocket(server); return new Response(null, &#123; status: 101, webSocket: client, &#125;); &#125; return new Response(&#x27;Not found&#x27;, &#123; status: 404 &#125;); &#125; async webSocketMessage(ws: WebSocket, message: string | ArrayBuffer) &#123; // 处理 WebSocket 消息 const data = JSON.parse(message as string); if (data.type === &#x27;reset&#x27;) &#123; this.count = 0; await this.state.storage.put(&#x27;count&#x27;, 0); ws.send(JSON.stringify(&#123; type: &#x27;reset&#x27;, count: 0 &#125;)); &#125; &#125;&#125;// 在 Worker 中使用 Durable Objectasync function handleRealtime(request: Request, env: Env): Promise&lt;Response&gt; &#123; const id = env.COUNTER.idFromName(&#x27;global-counter&#x27;); const stub = env.COUNTER.get(id); return stub.fetch(request);&#125;
2.4 Workers 与 Hono 框架// src/app.ts - Hono 边缘框架import &#123; Hono &#125; from &#x27;hono&#x27;;import &#123; cors &#125; from &#x27;hono/cors&#x27;;import &#123; bearerAuth &#125; from &#x27;hono/bearer-auth&#x27;;import &#123; logger &#125; from &#x27;hono/logger&#x27;;import &#123; z &#125; from &#x27;zod&#x27;;import &#123; zValidator &#125; from &#x27;@hono/zod-validator&#x27;;const app = new Hono&lt;&#123; Bindings: Env &#125;&gt;();// 中间件链app.use(&#x27;*&#x27;, logger());app.use(&#x27;/api/*&#x27;, cors(&#123; origin: [&#x27;https://app.example.com&#x27;] &#125;));app.use(&#x27;/api/admin/*&#x27;, bearerAuth(&#123; token: process.env.ADMIN_TOKEN! &#125;));// 类型安全路由const createUserSchema = z.object(&#123; name: z.string().min(2).max(50), email: z.string().email(), role: z.enum([&#x27;user&#x27;, &#x27;admin&#x27;, &#x27;viewer&#x27;]),&#125;);app.post(&#x27;/api/users&#x27;, zValidator(&#x27;json&#x27;, createUserSchema), async (c) =&gt; &#123; const data = c.req.valid(&#x27;json&#x27;); const result = await c.env.DB.prepare( &#x27;INSERT INTO users (name, email, role, created_at) VALUES (?, ?, ?, ?) RETURNING *&#x27; ) .bind(data.name, data.email, data.role, new Date().toISOString()) .first(); return c.json(result, 201);&#125;);// 边缘流式响应app.get(&#x27;/api/events&#x27;, async (c) =&gt; &#123; const stream = new ReadableStream(&#123; async start(controller) &#123; const encoder = new TextEncoder(); for (let i = 0; i &lt; 100; i++) &#123; const event = &#123; id: i, timestamp: Date.now() &#125;; controller.enqueue( encoder.encode(`data: $&#123;JSON.stringify(event)&#125;\n\n`) ); await new Promise((r) =&gt; setTimeout(r, 1000)); &#125; controller.close(); &#125;, &#125;); return new Response(stream, &#123; headers: &#123; &#x27;Content-Type&#x27;: &#x27;text/event-stream&#x27;, &#x27;Cache-Control&#x27;: &#x27;no-cache&#x27;, Connection: &#x27;keep-alive&#x27;, &#125;, &#125;);&#125;);export default app;
3. Deno Deploy 与 TypeScript 边缘运行时3.1 Deno Deploy 架构┌──────────────────────────────────────┐│ Deno Deploy 全球网络 ││ 35+ 区域 · V8 引擎 · TypeScript 原生 │├──────────────────────────────────────┤│ Fresh 2.x 框架 ││ ├── Islands Architecture（岛屿架构） ││ ├── 零 JS 默认 · 按需水合 ││ ├── 边缘中间件 ││ └── 流式 SSR │├──────────────────────────────────────┤│ Deno KV（全球分布式 SQLite） ││ ├── 强一致读 ││ ├── 事务支持 ││ └── 变更通知（Watch） │└──────────────────────────────────────┘
3.2 Fresh 2.x 岛屿架构// routes/index.tsx - Fresh 2.x 页面import &#123; useSignal &#125; from &#x27;@preact/signals&#x27;;import Counter from &#x27;../islands/Counter.tsx&#x27;;import SearchBox from &#x27;../islands/SearchBox.tsx&#x27;;export default function Home() &#123; return ( &lt;main&gt; &lt;h1&gt;边缘优先应用&lt;/h1&gt; &lt;p&gt;默认零 JavaScript，交互组件按需水合&lt;/p&gt; &#123;/* 岛屿组件：仅在客户端加载 JS */&#125; &lt;Counter start=&#123;0&#125; /&gt; &lt;SearchBox /&gt; &lt;/main&gt; );&#125;// islands/Counter.tsx - 客户端交互岛屿import &#123; useSignal &#125; from &#x27;@preact/signals&#x27;;interface CounterProps &#123; start: number;&#125;export default function Counter(&#123; start &#125;: CounterProps) &#123; const count = useSignal(start); return ( &lt;div class=&quot;counter&quot;&gt; &lt;p&gt;Count: &#123;count&#125;&lt;/p&gt; &lt;button onClick=&#123;() =&gt; count.value -= 1&#125;&gt;-1&lt;/button&gt; &lt;button onClick=&#123;() =&gt; count.value += 1&#125;&gt;+1&lt;/button&gt; &lt;/div&gt; );&#125;// islands/SearchBox.tsx - 边缘搜索import &#123; useSignal &#125; from &#x27;@preact/signals&#x27;;import &#123; useCallback &#125; from &#x27;preact/hooks&#x27;;export default function SearchBox() &#123; const query = useSignal(&#x27;&#x27;); const results = useSignal&lt;string[]&gt;([]); const loading = useSignal(false); const search = useCallback(async () =&gt; &#123; loading.value = true; try &#123; const res = await fetch(`/api/search?q=$&#123;encodeURIComponent(query.value)&#125;`); results.value = await res.json(); &#125; finally &#123; loading.value = false; &#125; &#125;, [query.value]); return ( &lt;div class=&quot;search-box&quot;&gt; &lt;input type=&quot;search&quot; value=&#123;query&#125; onInput=&#123;(e) =&gt; (query.value = e.currentTarget.value)&#125; onKeyDown=&#123;(e) =&gt; e.key === &#x27;Enter&#x27; &amp;&amp; search()&#125; placeholder=&quot;搜索...&quot; /&gt; &#123;loading.value &amp;&amp; &lt;span&gt;搜索中...&lt;/span&gt;&#125; &lt;ul&gt; &#123;results.value.map((item) =&gt; ( &lt;li&gt;&#123;item&#125;&lt;/li&gt; ))&#125; &lt;/ul&gt; &lt;/div&gt; );&#125;
3.3 Deno KV 边缘数据库// lib/kv.ts - Deno KV 操作封装interface User &#123; id: string; name: string; email: string; createdAt: string;&#125;const kv = await Deno.openKv();// 写入async function createUser(user: User) &#123; const res = await kv.atomic() .set([&#x27;users&#x27;, user.id], user) .set([&#x27;users_by_email&#x27;, user.email], user.id) .set([&#x27;users:created&#x27;, user.createdAt, user.id], user) .commit(); if (!res.ok) throw new Error(`KV write failed: $&#123;res&#125;`);&#125;// 读取async function getUser(id: string): Promise&lt;User | null&gt; &#123; const entry = await kv.get&lt;User&gt;([&#x27;users&#x27;, id]); return entry.value;&#125;// 列表查询（范围扫描）async function listUsers(options?: &#123; limit?: number; cursor?: string &#125;) &#123; const iter = kv.list&lt;User&gt;(&#123; prefix: [&#x27;users&#x27;] &#125;, &#123; limit: options?.limit ?? 20, cursor: options?.cursor, &#125;); const users: User[] = []; for await (const entry of iter) &#123; users.push(entry.value); &#125; return &#123; users, cursor: iter.cursor &#125;;&#125;// 事务性计数（原子操作）async function incrementPageView(pageId: string): Promise&lt;number&gt; &#123; const key = [&#x27;pageviews&#x27;, pageId]; while (true) &#123; const entry = await kv.get&lt;number&gt;(key); const current = entry.value ?? 0; const res = await kv.atomic() .check(entry) .set(key, current + 1) .commit(); if (res.ok) return current + 1; &#125;&#125;// 变更通知（Watch）function watchUserChanges(userId: string) &#123; const stream = kv.watch([[&#x27;users&#x27;, userId]]); (async () =&gt; &#123; for await (const entry of stream) &#123; console.log(&#x27;User changed:&#x27;, entry[0].value); // 推送 WebSocket 通知等 &#125; &#125;)();&#125;
4. 边缘 WebAssembly 运行时4.1 Fastly Compute@Edge// src/main.rs - Fastly Wasm 边缘处理#![no_main]use fastly::&#123;Error, Request, Response&#125;;use fastly::http::StatusCode;#[fastly::main]fn main(mut req: Request) -&gt; Result&lt;Response, Error&gt; &#123; let url = req.get_url(); // 边缘 A/B 测试路由 let ab_group = get_ab_group(&amp;req); match ab_group &#123; Group::A =&gt; &#123; req.set_header(&quot;x-ab-group&quot;, &quot;a&quot;); req.set_url(&quot;https://origin-a.example.com&quot;); &#125; Group::B =&gt; &#123; req.set_header(&quot;x-ab-group&quot;, &quot;b&quot;); req.set_url(&quot;https://origin-b.example.com&quot;); &#125; &#125; // 边缘图像变换 if url.path().starts_with(&quot;/images/&quot;) &#123; return handle_image_transform(req); &#125; // 边缘认证检查 if url.path().starts_with(&quot;/api/&quot;) &#123; if !validate_token(&amp;req) &#123; return Ok(Response::from_status(StatusCode::UNAUTHORIZED) .with_body_text_plain(&quot;Unauthorized&quot;)); &#125; &#125; // 发送到源站 let mut resp = req.send(&quot;origin&quot;)?; // 边缘响应头注入 resp.set_header(&quot;x-edge-node&quot;, fastly::geo::geoip().as_ref() .map(|g| g.city()) .unwrap_or(&quot;unknown&quot;)); Ok(resp)&#125;fn handle_image_transform(mut req: Request) -&gt; Result&lt;Response, Error&gt; &#123; use fastly::image::Image; let resp = req.send(&quot;origin&quot;)?; let body = resp.into_body(); let image = Image::from_body(body)?; let transformed = image .resize(800, 600, fastly::image::Fit::Cover) .format(fastly::image::Format::Auto) .quality(85) .to_webp(); Ok(Response::from_status(StatusCode::OK) .with_body(transformed) .with_header(&quot;content-type&quot;, &quot;image/webp&quot;) .with_header(&quot;cache-control&quot;, &quot;public, max-age=31536000&quot;))&#125;
4.2 Spin 框架（Fermyon）// src/lib.rs - Spin Serverless Wasmuse spin_sdk::http::&#123;Request, Response, IntoResponse, Router, Route&#125;;use spin_sdk::http::params;use serde::&#123;Deserialize, Serialize&#125;;#[derive(Deserialize)]struct CreateTask &#123; title: String, description: Option&lt;String&gt;,&#125;#[derive(Serialize)]struct Task &#123; id: String, title: String, description: Option&lt;String&gt;, status: String,&#125;struct HttpComponent;#[spin_sdk::http_component]fn handle_request(req: Request, _res: ()) -&gt; impl IntoResponse &#123; let mut router = Router::new(); router.get(&quot;/api/tasks&quot;, HttpComponent::list_tasks); router.post(&quot;/api/tasks&quot;, HttpComponent::create_task); router.get(&quot;/api/tasks/:id&quot;, HttpComponent::get_task); router.run(req, _res)&#125;impl HttpComponent &#123; fn list_tasks(_req: Request, _params: params::Params) -&gt; impl IntoResponse &#123; // Spin KV 存储 let tasks = spin_sdk::key_value::open(&quot;tasks&quot;) .expect(&quot;Failed to open KV store&quot;); let keys = tasks.get_keys().expect(&quot;Failed to get keys&quot;); let mut result: Vec&lt;Task&gt; = Vec::new(); for key in keys &#123; if let Ok(Some(data)) = tasks.get_json::&lt;Task&gt;(&amp;key) &#123; result.push(data); &#125; &#125; Response::json(&amp;result) &#125; fn create_task(req: Request, _params: params::Params) -&gt; impl IntoResponse &#123; let body: CreateTask = req.json().expect(&quot;Invalid JSON&quot;); let id = uuid::Uuid::new_v4().to_string(); let task = Task &#123; id: id.clone(), title: body.title, description: body.description, status: &quot;pending&quot;.to_string(), &#125;; let tasks = spin_sdk::key_value::open(&quot;tasks&quot;).expect(&quot;KV&quot;); tasks.set_json(&amp;id, &amp;task).expect(&quot;Set failed&quot;); Response::builder() .status(201) .header(&quot;location&quot;, format!(&quot;/api/tasks/&#123;&#125;&quot;, id)) .json(&amp;task) &#125; fn get_task(_req: Request, params: params::Params) -&gt; impl IntoResponse &#123; let id = params.get(&quot;id&quot;).unwrap(); let tasks = spin_sdk::key_value::open(&quot;tasks&quot;).expect(&quot;KV&quot;); match tasks.get_json::&lt;Task&gt;(&amp;id) &#123; Ok(Some(task)) =&gt; Response::json(&amp;task), _ =&gt; Response::builder().status(404).body(&quot;Not found&quot;), &#125; &#125;&#125;
5. 边缘 AI 推理5.1 Cloudflare Workers AI// src/ai-worker.ts - 边缘 AI 推理export default &#123; async fetch(request: Request, env: Env): Promise&lt;Response&gt; &#123; const url = new URL(request.url); // 文本分类 if (url.pathname === &#x27;/api/classify&#x27;) &#123; const &#123; text &#125; = await request.json() as &#123; text: string &#125;; const result = await env.AI.run(&#x27;@cf/huggingface/distilbert-sst-2-int8&#x27;, &#123; inputs: text, &#125;); return Response.json(result); &#125; // 图像生成 if (url.pathname === &#x27;/api/generate-image&#x27;) &#123; const &#123; prompt &#125; = await request.json() as &#123; prompt: string &#125;; const result = await env.AI.run(&#x27;@cf/stabilityai/stable-diffusion-xl-base-1.0&#x27;, &#123; prompt, num_steps: 20, &#125;); return new Response(result, &#123; headers: &#123; &#x27;Content-Type&#x27;: &#x27;image/png&#x27; &#125;, &#125;); &#125; // 文本嵌入（向量搜索） if (url.pathname === &#x27;/api/embed&#x27;) &#123; const &#123; text &#125; = await request.json() as &#123; text: string &#125;; const embeddings = await env.AI.run(&#x27;@cf/baai/bge-base-en-v1.5&#x27;, &#123; inputs: [text], &#125;); // 存入 Vectorize 向量数据库 const id = crypto.randomUUID(); await env.VECTORIZE.upsert([&#123; id, values: embeddings.data[0], metadata: &#123; text, createdAt: new Date().toISOString() &#125;, &#125;]); return Response.json(&#123; id, dimensions: embeddings.data[0].length &#125;); &#125; // 向量相似搜索 if (url.pathname === &#x27;/api/search&#x27;) &#123; const &#123; query, topK = 5 &#125; = await request.json() as &#123; query: string; topK?: number &#125;; const embeddings = await env.AI.run(&#x27;@cf/baai/bge-base-en-v1.5&#x27;, &#123; inputs: [query], &#125;); const matches = await env.VECTORIZE.query(embeddings.data[0], &#123; topK, returnMetadata: true, &#125;); return Response.json(matches); &#125; return new Response(&#x27;Not found&#x27;, &#123; status: 404 &#125;); &#125;,&#125;;
5.2 边缘 RAG（检索增强生成）// src/rag.ts - 边缘 RAG 管线interface RAGContext &#123; question: string; topK: number; systemPrompt?: string;&#125;async function ragPipeline(request: Request, env: Env): Promise&lt;Response&gt; &#123; const &#123; question, topK = 3, systemPrompt &#125;: RAGContext = await request.json(); // 1. 问题向量化 const questionEmbedding = await env.AI.run(&#x27;@cf/baai/bge-base-en-v1.5&#x27;, &#123; inputs: [question], &#125;); // 2. 向量检索相关文档 const searchResults = await env.VECTORIZE.query(questionEmbedding.data[0], &#123; topK, returnMetadata: &#x27;all&#x27;, &#125;); // 3. 构建上下文 const context = searchResults.matches .map((match, i) =&gt; `[$&#123;i + 1&#125;] $&#123;match.metadata?.text&#125;`) .join(&#x27;\n\n&#x27;); // 4. 流式生成回答 const messages = [ &#123; role: &#x27;system&#x27;, content: systemPrompt || &#x27;基于提供的上下文回答问题。如果上下文中没有相关信息，请说明。&#x27;, &#125;, &#123; role: &#x27;user&#x27;, content: `上下文：\n$&#123;context&#125;\n\n问题：$&#123;question&#125;`, &#125;, ]; const stream = await env.AI.run(&#x27;@cf/meta/llama-3.1-8b-instruct&#x27;, &#123; messages, stream: true, max_tokens: 512, &#125;); // 5. 返回 SSE 流 return new Response( new ReadableStream(&#123; async start(controller) &#123; const encoder = new TextEncoder(); for await (const chunk of stream) &#123; const data = &#123; content: chunk.response &#125;; controller.enqueue(encoder.encode(`data: $&#123;JSON.stringify(data)&#125;\n\n`)); &#125; controller.enqueue(encoder.encode(&#x27;data: [DONE]\n\n&#x27;)); controller.close(); &#125;, &#125;), &#123; headers: &#123; &#x27;Content-Type&#x27;: &#x27;text/event-stream&#x27;, &#x27;Cache-Control&#x27;: &#x27;no-cache&#x27;, Connection: &#x27;keep-alive&#x27;, &#125;, &#125; );&#125;
6. 边缘数据一致性6.1 CRDT 边缘同步// lib/crdt.ts - 边缘 CRDT 文档同步import &#123; Doc, encodeStateAsUpdate, applyUpdate, mergeUpdates &#125; from &#x27;yjs&#x27;;interface SyncMessage &#123; type: &#x27;sync-step-1&#x27; | &#x27;sync-step-2&#x27; | &#x27;update&#x27;; data: Uint8Array;&#125;// 边缘文档合并async function mergeDocumentUpdates( updates: Uint8Array[], env: Env, docId: string): Promise&lt;Uint8Array&gt; &#123; // 合并多个更新为单个 const merged = mergeUpdates(updates); // 存储到 Durable Object const id = env.DOCS.idFromName(docId); const stub = env.DOCS.get(id); const response = await stub.fetch(&#x27;https://internal/apply&#x27;, &#123; method: &#x27;POST&#x27;, body: merged, &#125;); return new Uint8Array(await response.arrayBuffer());&#125;// Durable Object 文档状态管理export class DocumentSync &#123; private doc: Doc; private state: DurableObjectState; constructor(state: DurableObjectState) &#123; this.state = state; this.doc = new Doc(); state.blockConcurrencyWhile(async () =&gt; &#123; const stored = await state.storage.get&lt;Uint8Array&gt;(&#x27;doc-state&#x27;); if (stored) &#123; applyUpdate(this.doc, stored); &#125; &#125;); &#125; async fetch(request: Request) &#123; const url = new URL(request.url); if (url.pathname === &#x27;/sync&#x27; &amp;&amp; request.method === &#x27;POST&#x27;) &#123; const update = new Uint8Array(await request.arrayBuffer()); applyUpdate(this.doc, update); // 持久化状态 const state = encodeStateAsUpdate(this.doc); await this.state.storage.put(&#x27;doc-state&#x27;, state); // 广播给所有连接的 WebSocket 客户端 for (const ws of this.state.getWebSockets()) &#123; ws.send(state); &#125; return new Response(state); &#125; if (url.pathname === &#x27;/ws&#x27;) &#123; const pair = new TransformStream(); const writer = pair.writable.getWriter(); this.state.acceptWebSocket(pair.readable as any); // 发送当前完整状态 const state = encodeStateAsUpdate(this.doc); writer.write(state); return new Response(null, &#123; status: 101, webSocket: pair.readable as any, &#125;); &#125; return new Response(&#x27;Not found&#x27;, &#123; status: 404 &#125;); &#125;&#125;
6.2 边缘缓存策略// lib/cache-strategy.ts - 边缘缓存策略type CacheStrategy = &#x27;cache-first&#x27; | &#x27;network-first&#x27; | &#x27;stale-while-revalidate&#x27; | &#x27;cache-only&#x27;;interface CacheOptions &#123; strategy: CacheStrategy; cacheName: string; maxAge?: number; // 秒 staleMaxAge?: number; // 秒 varyHeaders?: string[];&#125;async function cachedFetch( request: Request, options: CacheOptions): Promise&lt;Response&gt; &#123; const cache = await caches.open(options.cacheName); const cacheKey = buildCacheKey(request, options.varyHeaders); switch (options.strategy) &#123; case &#x27;cache-first&#x27;: &#123; const cached = await cache.match(cacheKey); if (cached &amp;&amp; !isExpired(cached, options.maxAge)) &#123; return cached; &#125; const response = await fetch(request); if (response.ok) &#123; await cache.put(cacheKey, tagResponse(response, options)); &#125; return response; &#125; case &#x27;network-first&#x27;: &#123; try &#123; const response = await fetch(request); if (response.ok) &#123; await cache.put(cacheKey, tagResponse(response, options)); &#125; return response; &#125; catch &#123; const cached = await cache.match(cacheKey); if (cached) return cached; throw new Error(&#x27;Network error and no cache available&#x27;); &#125; &#125; case &#x27;stale-while-revalidate&#x27;: &#123; const cached = await cache.match(cacheKey); // 后台重新验证 const revalidate = async () =&gt; &#123; try &#123; const response = await fetch(request); if (response.ok) &#123; await cache.put(cacheKey, tagResponse(response, options)); &#125; &#125; catch &#123; /* ignore */ &#125; &#125;; if (cached) &#123; if (isStale(cached, options.maxAge, options.staleMaxAge)) &#123; // 返回过期缓存，但后台更新 return addHeader(cached, &#x27;X-Cache&#x27;, &#x27;STALE&#x27;); &#125; return addHeader(cached, &#x27;X-Cache&#x27;, &#x27;HIT&#x27;); &#125; // 无缓存，等待网络 const response = await fetch(request); if (response.ok) &#123; await cache.put(cacheKey, tagResponse(response, options)); &#125; return response; &#125; case &#x27;cache-only&#x27;: &#123; const cached = await cache.match(cacheKey); if (!cached) throw new Error(&#x27;Not in cache&#x27;); return cached; &#125; &#125;&#125;function buildCacheKey(request: Request, varyHeaders?: string[]): Request &#123; if (!varyHeaders?.length) return request; const url = new URL(request.url); const varyParts = varyHeaders .map((h) =&gt; `$&#123;h&#125;:$&#123;request.headers.get(h) || &#x27;&#x27;&#125;`) .join(&#x27;|&#x27;); url.searchParams.set(&#x27;__vary&#x27;, btoa(varyParts)); return new Request(url.toString(), &#123; method: &#x27;GET&#x27; &#125;);&#125;function isExpired(response: Response, maxAge?: number): boolean &#123; if (!maxAge) return false; const cached = response.headers.get(&#x27;x-cached-at&#x27;); if (!cached) return true; return (Date.now() - Number(cached)) / 1000 &gt; maxAge;&#125;function isStale(response: Response, maxAge?: number, staleMaxAge?: number): boolean &#123; if (!maxAge || !staleMaxAge) return false; const cached = response.headers.get(&#x27;x-cached-at&#x27;); if (!cached) return true; const age = (Date.now() - Number(cached)) / 1000; return age &gt; maxAge &amp;&amp; age &lt;= maxAge + staleMaxAge;&#125;function tagResponse(response: Response, options: CacheOptions): Response &#123; const headers = new Headers(response.headers); headers.set(&#x27;x-cached-at&#x27;, String(Date.now())); headers.set(&#x27;x-cache-strategy&#x27;, options.strategy); return new Response(response.body, &#123; ...response, headers &#125;);&#125;function addHeader(response: Response, key: string, value: string): Response &#123; const headers = new Headers(response.headers); headers.set(key, value); return new Response(response.body, &#123; ...response, headers &#125;);&#125;
7. 边缘可观测性7.1 边缘日志与追踪// lib/edge-observability.ts - 边缘可观测性interface SpanData &#123; traceId: string; spanId: string; parentSpanId?: string; name: string; startTime: number; endTime?: number; attributes: Record&lt;string, string | number | boolean&gt;; status: &#x27;ok&#x27; | &#x27;error&#x27;;&#125;// 边缘追踪上下文传播function extractTraceContext(request: Request): &#123; traceId: string; spanId: string &#125; &#123; const traceparent = request.headers.get(&#x27;traceparent&#x27;); if (traceparent) &#123; const [, traceId, parentSpanId] = traceparent.split(&#x27;-&#x27;); return &#123; traceId, spanId: generateSpanId() &#125;; &#125; return &#123; traceId: generateTraceId(), spanId: generateSpanId(), &#125;;&#125;function generateTraceId(): string &#123; const bytes = new Uint8Array(16); crypto.getRandomValues(bytes); return Array.from(bytes, (b) =&gt; b.toString(16).padStart(2, &#x27;0&#x27;)).join(&#x27;&#x27;);&#125;function generateSpanId(): string &#123; const bytes = new Uint8Array(8); crypto.getRandomValues(bytes); return Array.from(bytes, (b) =&gt; b.toString(16).padStart(2, &#x27;0&#x27;)).join(&#x27;&#x27;);&#125;// 边缘指标收集class EdgeMetrics &#123; private buffer: Map&lt;string, number[]&gt; = new Map(); private flushInterval: number; constructor(private env: Env, flushInterval = 10_000) &#123; this.flushInterval = flushInterval; &#125; histogram(name: string, value: number, labels?: Record&lt;string, string&gt;) &#123; const key = this.buildKey(name, labels); if (!this.buffer.has(key)) &#123; this.buffer.set(key, []); &#125; this.buffer.get(key)!.push(value); &#125; counter(name: string, labels?: Record&lt;string, string&gt;) &#123; this.histogram(`$&#123;name&#125;.count`, 1, labels); &#125; async flush(): Promise&lt;void&gt; &#123; if (this.buffer.size === 0) return; const metrics: Array&lt;&#123; name: string; labels: Record&lt;string, string&gt;; values: number[] &#125;&gt; = []; for (const [key, values] of this.buffer) &#123; const &#123; name, labels &#125; = this.parseKey(key); metrics.push(&#123; name, labels, values &#125;); &#125; this.buffer.clear(); // 异步发送到分析后端 await this.env.QUEUE.send(&#123; type: &#x27;metrics&#x27;, timestamp: Date.now(), metrics, &#125;); &#125; private buildKey(name: string, labels?: Record&lt;string, string&gt;): string &#123; if (!labels) return name; const sorted = Object.entries(labels).sort(([a], [b]) =&gt; a.localeCompare(b)); return `$&#123;name&#125;|$&#123;sorted.map(([k, v]) =&gt; `$&#123;k&#125;=$&#123;v&#125;`).join(&#x27;,&#x27;)&#125;`; &#125; private parseKey(key: string): &#123; name: string; labels: Record&lt;string, string&gt; &#125; &#123; const [name, labelStr] = key.split(&#x27;|&#x27;); const labels: Record&lt;string, string&gt; = &#123;&#125;; if (labelStr) &#123; for (const pair of labelStr.split(&#x27;,&#x27;)) &#123; const [k, v] = pair.split(&#x27;=&#x27;); labels[k] = v; &#125; &#125; return &#123; name, labels &#125;; &#125;&#125;// 边缘请求中间件export async function withObservability( request: Request, env: Env, handler: (req: Request) =&gt; Promise&lt;Response&gt;): Promise&lt;Response&gt; &#123; const metrics = new EdgeMetrics(env); const &#123; traceId, spanId &#125; = extractTraceContext(request); const startTime = Date.now(); try &#123; const response = await handler(request); metrics.histogram(&#x27;request.duration&#x27;, Date.now() - startTime, &#123; method: request.method, path: new URL(request.url).pathname, status: String(response.status), &#125;); metrics.counter(&#x27;request.total&#x27;, &#123; method: request.method, status: String(response.status), &#125;); // 注入追踪头 const headers = new Headers(response.headers); headers.set(&#x27;x-trace-id&#x27;, traceId); headers.set(&#x27;x-span-id&#x27;, spanId); headers.set(&#x27;server-timing&#x27;, `total;dur=$&#123;Date.now() - startTime&#125;`); // 异步刷新指标 await metrics.flush(); return new Response(response.body, &#123; ...response, headers &#125;); &#125; catch (error) &#123; metrics.histogram(&#x27;request.duration&#x27;, Date.now() - startTime, &#123; method: request.method, status: &#x27;500&#x27;, &#125;); metrics.counter(&#x27;request.error&#x27;, &#123; method: request.method, error: error instanceof Error ? error.name : &#x27;Unknown&#x27;, &#125;); await metrics.flush(); throw error; &#125;&#125;
8. 边缘安全8.1 边缘安全中间件// lib/edge-security.ts - 边缘安全防护interface SecurityConfig &#123; rateLimit: &#123; window: number; max: number &#125;; cors: &#123; origins: string[]; methods: string[] &#125;; botProtection: boolean; ipAllowlist?: string[];&#125;// 边缘速率限制（基于 KV）async function rateLimit( request: Request, env: Env, config: &#123; window: number; max: number &#125;): Promise&lt;Response | null&gt; &#123; const ip = request.headers.get(&#x27;CF-Connecting-IP&#x27;) || &#x27;unknown&#x27;; const key = `ratelimit:$&#123;ip&#125;:$&#123;Math.floor(Date.now() / (config.window * 1000))&#125;`; const current = await env.KV.get(key); const count = current ? parseInt(current) : 0; if (count &gt;= config.max) &#123; return new Response(&#x27;Rate limit exceeded&#x27;, &#123; status: 429, headers: &#123; &#x27;Retry-After&#x27;: String(config.window), &#x27;X-RateLimit-Limit&#x27;: String(config.max), &#x27;X-RateLimit-Remaining&#x27;: &#x27;0&#x27;, &#125;, &#125;); &#125; await env.KV.put(key, String(count + 1), &#123; expirationTtl: config.window * 2 &#125;); return null; // 继续处理&#125;// 边缘 WAF（Web 应用防火墙）function wafCheck(request: Request): Response | null &#123; const url = new URL(request.url); const headers = request.headers; // SQL 注入检测 const sqlPatterns = [ /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|UNION)\b.*\b(FROM|INTO|SET|TABLE)\b)/i, /(--|;|\/\*|\*\/)/, /(\bOR\b\s+\d+\s*=\s*\d+)/i, ]; const body = request.method === &#x27;POST&#x27; ? request.clone().text() : &#x27;&#x27;; for (const pattern of sqlPatterns) &#123; if (pattern.test(url.search) || pattern.test(body)) &#123; return new Response(&#x27;Blocked by WAF&#x27;, &#123; status: 403 &#125;); &#125; &#125; // XSS 检测 const xssPatterns = [/&lt;script[\s&gt;]/i, /javascript:/i, /on\w+\s*=/i]; for (const pattern of xssPatterns) &#123; if (pattern.test(url.search) || pattern.test(body)) &#123; return new Response(&#x27;Blocked by WAF&#x27;, &#123; status: 403 &#125;); &#125; &#125; // 路径遍历检测 if (url.pathname.includes(&#x27;..&#x27;) || url.pathname.includes(&#x27;%2e%2e&#x27;)) &#123; return new Response(&#x27;Blocked by WAF&#x27;, &#123; status: 403 &#125;); &#125; return null; // 通过检查&#125;// 边缘安全头注入function addSecurityHeaders(response: Response): Response &#123; const headers = new Headers(response.headers); headers.set(&#x27;X-Content-Type-Options&#x27;, &#x27;nosniff&#x27;); headers.set(&#x27;X-Frame-Options&#x27;, &#x27;DENY&#x27;); headers.set(&#x27;X-XSS-Protection&#x27;, &#x27;0&#x27;); headers.set(&#x27;Referrer-Policy&#x27;, &#x27;strict-origin-when-cross-origin&#x27;); headers.set(&#x27;Permissions-Policy&#x27;, &#x27;camera=(), microphone=(), geolocation=()&#x27;); headers.set( &#x27;Content-Security-Policy&#x27;, &quot;default-src &#x27;self&#x27;; script-src &#x27;self&#x27; &#x27;wasm-unsafe-eval&#x27;; style-src &#x27;self&#x27; &#x27;unsafe-inline&#x27;; img-src &#x27;self&#x27; data: https:; connect-src &#x27;self&#x27; https://api.example.com&quot; ); headers.set( &#x27;Strict-Transport-Security&#x27;, &#x27;max-age=63072000; includeSubDomains; preload&#x27; ); return new Response(response.body, &#123; ...response, headers &#125;);&#125;// 边缘 IP 地理位置过滤function geoFilter(request: Request, allowedCountries: string[]): Response | null &#123; const country = request.headers.get(&#x27;CF-IPCountry&#x27;) || &#x27;unknown&#x27;; if (!allowedCountries.includes(country)) &#123; return new Response(&#x27;Access denied in your region&#x27;, &#123; status: 403 &#125;); &#125; return null;&#125;
9. 边缘部署与 CI&#x2F;CD9.1 Wrangler 配置与部署# wrangler.toml - Cloudflare Workers 配置name = &quot;edge-app&quot;main = &quot;src/index.ts&quot;compatibility_date = &quot;2026-09-01&quot;compatibility_flags = [&quot;nodejs_compat&quot;]# 环境变量[vars]ENVIRONMENT = &quot;production&quot;# KV 命名空间绑定[[kv_namespaces]]binding = &quot;KV&quot;id = &quot;abc123&quot;preview_id = &quot;def456&quot;# D1 数据库绑定[[d1_databases]]binding = &quot;DB&quot;database_name = &quot;edge-db&quot;database_id = &quot;xyz789&quot;# R2 存储桶绑定[[r2_buckets]]binding = &quot;BUCKET&quot;bucket_name = &quot;edge-assets&quot;# Durable Objects[[durable_objects.bindings]]name = &quot;COUNTER&quot;class_name = &quot;RequestCounter&quot;[[migrations]]tag = &quot;v1&quot;new_classes = [&quot;RequestCounter&quot;, &quot;DocumentSync&quot;]# 路由配置[[routes]]pattern = &quot;api.example.com/*&quot;zone_name = &quot;example.com&quot;# 队列绑定[[queues.producers]]binding = &quot;QUEUE&quot;queue = &quot;analytics-events&quot;[[queues.consumers]]queue = &quot;analytics-events&quot;max_batch_size = 100max_batch_timeout = 30
9.2 GitHub Actions 边缘部署# .github/workflows/deploy.ymlname: Deploy Edge Workeron: push: branches: [main] pull_request: branches: [main]jobs: test: runs-on: ubuntu-latest steps: - uses: actions/checkout@v4 - uses: oven-sh/setup-bun@v2 with: bun-version: latest - run: bun install --frozen-lockfile - run: bun run typecheck - run: bun run test # Miniflare 本地测试 - run: bun run test:e2e env: CLOUDFLARE_API_TOKEN: $&#123;&#123; secrets.CF_API_TOKEN &#125;&#125; deploy-preview: needs: test if: github.event_name == &#x27;pull_request&#x27; runs-on: ubuntu-latest steps: - uses: actions/checkout@v4 - uses: oven-sh/setup-bun@v2 - run: bun install --frozen-lockfile - name: Deploy Preview uses: cloudflare/wrangler-action@v3 with: apiToken: $&#123;&#123; secrets.CF_API_TOKEN &#125;&#125; command: deploy --env preview --name edge-app-pr-$&#123;&#123; github.event.number &#125;&#125; - name: Comment PR uses: actions/github-script@v7 with: script: | github.rest.issues.createComment(&#123; issue_number: context.issue.number, owner: context.repo.owner, repo: context.repo.repo, body: `🚀 Preview deployed: https://edge-app-pr-$&#123;context.issue.number&#125;.workers.dev` &#125;) deploy-production: needs: test if: github.ref == &#x27;refs/heads/main&#x27; runs-on: ubuntu-latest environment: production steps: - uses: actions/checkout@v4 - uses: oven-sh/setup-bun@v2 - run: bun install --frozen-lockfile - name: Deploy Production uses: cloudflare/wrangler-action@v3 with: apiToken: $&#123;&#123; secrets.CF_API_TOKEN &#125;&#125; command: deploy --env production - name: Smoke Test run: | curl -f https://api.example.com/health || exit 1
10. 典型案例：CDN 边缘计算（个性化页面 + 动静分离）问题背景：跨境电商站点用户遍布 30 国，源站在美国：登录态用户的购物车&#x2F;货币&#x2F;语言都依赖源站动态渲染，东京用户 RTT 180ms，首页 TTFB 2.1s；大促时源站带宽费用暴涨。目标是：静态资源全球快，动态个性化也不能慢。 方案：动静分离 + 边缘个性化：静态走 CDN 缓存，个性化片段由 Cloudflare Worker 在边缘组装，Cookie&#x2F;会话不过源站： 东京用户 ──→ 边缘节点(东京) ├── 静态资源(JS/CSS/图片) ──→ Cache HIT，0 额外延迟 ├── HTML 外壳 ──→ Cache(按 URL+语言) HIT ├── Worker 边缘个性化： │ · 解析会话 Cookie → KV 查购物车数量(边缘 KV, &lt;10ms) │ · 货币/语言本地化、A/B 分流(stable hash) │ · SSE 转发(边缘 → 源站长连接) └── 仅&quot;结算/支付&quot;等强一致请求回源(美西，占比 &lt;3%)效果：TTFB 2.1s → 210ms；回源带宽 -92%；大促源站零扩容
层 策略 说明
静态资源 CDN 长缓存 + 指纹版本 sw-cacheable 1 年 + 版本号失效
HTML 外壳 短缓存（60s）+ 语言维度 Vary 全球近源命中
个性化片段 Worker 边缘组装 会话校验&#x2F;购物车&#x2F;A-B 在边缘
强一致请求 回源 + mTLS 支付&#x2F;库存写操作不缓存的场景
关键设计： // Cloudflare Worker：边缘缓存 + 个性化组装export default &#123; async fetch(request, env, ctx) &#123; const url = new URL(request.url); const lang = (request.headers.get(&#x27;accept-language&#x27;) || &#x27;en&#x27;).split(&#x27;,&#x27;)[0]; // 1. HTML 外壳：按 URL+语言 边缘缓存（Cache API，60s 微缓存） const cacheKey = new Request(`$&#123;url.origin&#125;$&#123;url.pathname&#125;?lang=$&#123;lang&#125;`, request); let shell = await env.ASSETS_CACHE.match(cacheKey); if (!shell) &#123; shell = await fetch(request, &#123; cf: &#123; cacheTtlByStatus: &#123; &#x27;200-299&#x27;: 60 &#125; &#125; &#125;); ctx.waitUntil(env.ASSETS_CACHE.put(cacheKey, shell.clone())); // 异步回填缓存 &#125; // 2. 个性化：会话 Cookie 在边缘校验（JWT 验签），购物车数查边缘 KV const session = await verifyJwt(request.headers.get(&#x27;cookie&#x27;)); // 边缘验签，不回源 const cartCount = session ? await env.CART_KV.get(`cart:$&#123;session.uid&#125;`, &#x27;json&#x27;) ?? 0 // 边缘 KV &lt;10ms : 0; // 3. A/B 分流：uid 稳定哈希，同一用户始终同组（边缘完成，源站无感） const bucket = session ? stableHash(session.uid) % 100 : 0; const html = await shell.text() .replace(&#x27;__CART_COUNT__&#x27;, String(cartCount)) .replace(&#x27;__AB__&#x27;, bucket &lt; 10 ? &#x27;variant-b&#x27; : &#x27;control&#x27;); return new Response(html, &#123; headers: &#123; &#x27;content-type&#x27;: &#x27;text/html; charset=utf-8&#x27; &#125; &#125;); &#125;&#125;
踩坑点：① 静态资源没带指纹版本，边缘缓存 1 年改版后用户看到旧 CSS——内容哈希文件名 + 不可变缓存头。② HTML 缓存键漏了语言维度，日本用户命中英文缓存——Vary&#x2F;缓存键必须覆盖所有影响内容的请求维度。③ 把购物车价格计算放边缘 KV，库存变了边缘还是旧价，用户结算价与展示价不符——边缘只做”展示级个性化”，强一致数据回源并在结算页二次确认。④ Worker 里同步 await 两个慢查询（购物车+推荐），串行叠加延迟——Promise.all 并行 + ctx.waitUntil 把非关键路径（埋点&#x2F;推荐）挪到响应后。⑤ 边缘 KV 写后读不一致（购物车刚加的 item 不显示），用户重复点击——写操作回源，读展示容忍秒级陈旧 + 客户端乐观更新。 11. 常见误用与陷阱
坑 现象&#x2F;后果 解法
静态资源无指纹 改版后用户见旧样式 内容哈希文件名 + immutable 缓存头
缓存键漏请求维度 多语言&#x2F;站点串缓存 键覆盖 URL+语言+站点等全部维度
边缘算强一致数据 展示价与结算价不一致 边缘只做展示个性化，一致性回源
边缘 KV 当强一致存储 写后读不一致，重复提交 写回源，读容忍陈旧 + 乐观更新
Worker 里串行慢调用 边缘延迟反而变高 Promise.all 并行 + waitUntil 后置
会话校验回源 每请求回源，边缘白干 JWT 边缘验签（JWKS 边缘缓存）
无降级预案 边缘故障等于全站故障 Worker 异常时回退纯 CDN 模式
日志只在边缘采样 安全事件无法审计 边缘结构化日志 → 中心聚合（Tail Worker）
跨境合规忽视 用户数据出境违规 按区域路由 + 数据本地驻留（EU→EU）
12. 速查卡片动静分离 = 静态长缓存(指纹) + HTML 微缓存(60s) + 回源仅强一致边缘个性化 = JWT 边缘验签 + KV 近源读 + stable hash 分流缓存键 = 覆盖所有影响内容的维度（URL/语言/站点/AB）数据一致性 = 展示级容忍陈旧；写操作与结算回源二次确认性能 = 非关键路径 waitUntil 后置；并行化边缘查询可靠 = Worker 异常降级回 CDN；边缘日志中心化聚合合规 = 区域路由 + 数据本地驻留（EU/EU）
